CustomField.formula:
IF(
    OR(ISBLANK(LeasingEndDate__c), ISBLANK(LeasingStartDate__c), ISBLANK(TEXT(PaymentTerm__c))),
    "0 installments",
    TEXT(
        ROUND(
            ((LeasingEndDate__c - LeasingStartDate__c) / 365) * VALUE(LEFT(TEXT(PaymentTerm__c), FIND(" ", TEXT(PaymentTerm__c)) - 1)), 
            0
        )
    ) & " installments"
)
